public class UrlBuilderTest {

    @Test
    public void newUrlBuilder() {
        URL inputUrl = new URL("http://test.com");
        UrlBuilder builder = new UrlBuilder(inputUrl);
        assert builder.u != null;
    }

    @Test
    public void newUrlBuilderWithQuery() {
        URL inputUrl = new URL("http://test.com?query=param");
        UrlBuilder builder = new UrlBuilder(inputUrl);
        assert builder.q != null;
    }

    @Test
    public void buildNormalUrl() {
        URL inputUrl = new URL("http://test.com");
        UrlBuilder builder = new UrlBuilder(inputUrl);
        assertEquals(inputUrl, builder.build());
    }

    @Test
    public void buildUrlWithQuery() throws MalformedURLException, URISyntaxException {
        URL inputUrl = new URL("http://test.com?query=param");
        UrlBuilder builder = new UrlBuilder(inputUrl);
        assertEquals(inputUrl, builder.build());
    }

    @Test
    public void appendKeyValNormalUrl() throws UnsupportedEncodingException {
        Connection.KeyVal kv = new Connection.KeyVal("key", "value");
        UrlBuilder builder = new UrlBuilder(new URL("http://test.com"));
        builder.appendKeyVal(kv);
        assertEquals("http://test.com?key=value", builder.build().toString());
    }

    @Test
    public void appendKeyValUrlWithQuery() throws UnsupportedEncodingException, MalformedURLException {
        Connection.KeyVal kv = new Connection.KeyVal("key", "value");
        UrlBuilder builder = new UrlBuilder(new URL("http://test.com?query=param"));
        builder.appendKeyVal(kv);
        assertEquals("http://test.com?key=value&query=param", builder.build().toString());
    }

    @Test
    public void decodePartNormalString() {
        String encoded = "test";
        String decoded = UrlBuilder.decodePart(encoded);
        assertEquals("test", decoded);
    }

    @Test
    public void decodePartEncodedString() throws UnsupportedEncodingException {
        String encoded = "%20test";
        String decoded = UrlBuilder.decodePart(encoded);
        assertEquals(" test ", decoded);
    }

